-- Dummy data for the UDM Alumni Tracer: 500 alumni (50 per college, batches 2019–2025) with survey answers,
-- 2 events and 5 jobs. Generated; run once on an empty alumni table (it refuses otherwise). One transaction.
--
-- HOW TO RUN: paste the whole file into the Neon SQL Editor (branch main) and Run. The last row should read
--   alumni 500 · alumni_with_account 500 · dummy_admins 1 · dummy_colleges 10 · surveys 325 · employment 325 · events 2 · jobs 5
--
-- ALUMNI ACCOUNTS (testing only):
--   * Every alumnus has an active alumni account, but NO PASSWORD (empty hash): nobody can sign in to them.
--   * Login:    firstname.lastname.N@example.com   (e.g. pauline.dizon.1@example.com, rica.cruz.2@example.com)
--   * For accounts you can sign in to, run "dummy_data copy.sql" instead (it has the shared password).
--
-- ADMIN AND COLLEGE ACCOUNTS (testing only): created, but NO PASSWORD (empty hash), so nobody can sign in to them.
--   * Admin    login: admin@example.com
--   * Colleges login: <code>.dean@example.com   (10 accounts)
--       cas.dean@example.com    CAS
--       cba.dean@example.com    CBA
--       cbpm.dean@example.com   CBPM
--       ccs.dean@example.com    CCS
--       ccj.dean@example.com    CCJ
--       coed.dean@example.com   COED
--       cet.dean@example.com    CET
--       chs.dean@example.com    CHS
--       claw.dean@example.com   CLAW
--       gs.dean@example.com     GS
--   * For staff accounts you can sign in to, run "dummy_data copy.sql" instead.
--
-- NOTES:
--   * Keep MFA_ENABLED=false on Render while testing: the 6-digit sign-in code is emailed, and @example.com has no inbox.
--   * Forgot password can't set one either: the reset email goes to @example.com, which has no inbox.
--   * Dummy data only. To remove it, run the wipe script (it deletes every alumni record and account),
--     then the dummy staff accounts: DELETE FROM user_account WHERE lower(email) LIKE '%@example.com';
--   * The 2 events start with no RSVPs. Generated by gen-dummy.php (fixed seed): re-running gives the same data.
BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM alumnus) THEN RAISE EXCEPTION 'alumnus is not empty: run the wipe first'; END IF;
  IF NOT EXISTS (SELECT 1 FROM v_active_cycle) THEN RAISE EXCEPTION 'no survey cycle: deploy once so LookupSeeder runs'; END IF;
  IF NOT EXISTS (SELECT 1 FROM user_account WHERE role = 'admin') THEN RAISE EXCEPTION 'no admin account'; END IF;
  IF EXISTS (SELECT 1 FROM user_account WHERE lower(email) LIKE '%@example.com') THEN RAISE EXCEPTION 'dummy accounts already exist'; END IF;
END $$;
-- Admin and college (dept) accounts
INSERT INTO user_account (email, password_hash, role, college_id, display_name, role_label, account_status, must_change_password)
SELECT v.email, CASE v.role WHEN 'admin' THEN '' ELSE '' END, v.role::user_role, c.college_id, v.name, v.label, 'active'::account_status, false
FROM (VALUES
  ('admin@example.com', 'admin', NULL, 'Dummy Admin', 'Administrator'),
  ('cas.dean@example.com', 'dept', 'CAS', 'College of Arts and Sciences (Dummy)', 'College Dean'),
  ('cba.dean@example.com', 'dept', 'CBA', 'College of Business Administration (Dummy)', 'College Dean'),
  ('cbpm.dean@example.com', 'dept', 'CBPM', 'College of Business and Public Management (Dummy)', 'College Dean'),
  ('ccs.dean@example.com', 'dept', 'CCS', 'College of Computing Studies (Dummy)', 'College Dean'),
  ('ccj.dean@example.com', 'dept', 'CCJ', 'College of Criminal Justice (Dummy)', 'College Dean'),
  ('coed.dean@example.com', 'dept', 'COED', 'College of Education (Dummy)', 'College Dean'),
  ('cet.dean@example.com', 'dept', 'CET', 'College of Engineering and Technology (Dummy)', 'College Dean'),
  ('chs.dean@example.com', 'dept', 'CHS', 'College of Health Sciences (Dummy)', 'College Dean'),
  ('claw.dean@example.com', 'dept', 'CLAW', 'College of Law (Dummy)', 'College Dean'),
  ('gs.dean@example.com', 'dept', 'GS', 'Graduate Studies (Dummy)', 'College Dean')
) v(email, role, college, name, label)
LEFT JOIN college c ON c.code = v.college;

