-- Sign-in accounts: one active alumni account per record, the record's email as login (no password: empty hash, sign-in always fails).
-- The login email wins over contact_email, so contact_email is cleared once linked.
INSERT INTO user_account (email, password_hash, role, display_name, account_status, must_change_password, created_at, updated_at)
SELECT a.contact_email, '', 'alumni'::user_role, a.first_name || ' ' || a.last_name, 'active'::account_status, false, a.created_at, a.created_at
FROM alumnus a;

UPDATE alumnus a SET user_id = u.user_id, contact_email = NULL
FROM user_account u WHERE u.role = 'alumni' AND lower(u.email) = lower(a.contact_email);

