-- Jobs (approved admin postings)
INSERT INTO job_posting (posted_by, reviewed_by, title, company, location, employment_type, salary_range, deadline, apply_via, description, source, approval_status, published_at)
SELECT u.user_id, u.user_id, v.title, v.company, v.loc, v.et::employment_type, v.salary, v.deadline::date, v.apply, v.descr, 'admin'::posting_source, 'approved'::approval_status, now()
FROM (SELECT user_id FROM user_account WHERE role = 'admin' ORDER BY user_id LIMIT 1) u,
(VALUES
  ('Junior Software Developer', 'Accenture Philippines', 'Taguig City · Hybrid', 'full_time', '₱28,000 – ₱35,000', '2026-12-15', 'careers.ph@accenture.example.com',
   'Build and maintain web applications with a delivery team. Open to fresh graduates of IT, CS and Computer Engineering programs.'),
  ('Staff Nurse', 'Ospital ng Maynila Medical Center', 'Malate, Manila · On-site', 'full_time', '₱36,619 (SG 15)', '2026-11-30', 'hr@onmc.example.com',
   'Provide nursing care in the medical-surgical ward. Must hold a valid PRC license; new passers are welcome to apply.'),
  ('Accounting Associate', 'SGV & Co.', 'Makati City · On-site', 'full_time', '₱25,000 – ₱30,000', '2026-12-10', 'https://careers.example.com/sgv',
   'Assist in audit engagements and financial statement preparation. For graduates of Accountancy and Accounting Information System.'),
  ('Customer Experience Specialist', 'Concentrix', 'Quezon City · On-site', 'full_time', '₱20,000 – ₱24,000', '2026-11-20', 'https://careers.example.com/concentrix',
   'Handle customer concerns for an international account over voice and chat. Graduates of any course; strong English communication required.'),
  ('Part-time Instructor, Criminology', 'Universidad de Manila', 'Manila · On-site', 'part_time', 'Per teaching hour', '2026-11-25', 'hrmdd@udm.edu.ph',
   'Teach criminology courses for the second semester. Licensed criminologist with a master''s degree (or units) preferred.')
) v(title, company, loc, et, salary, deadline, apply, descr);

-- Events
WITH admin AS (SELECT user_id FROM user_account WHERE role = 'admin' ORDER BY user_id LIMIT 1),
ev AS (
  INSERT INTO event (created_by, title, category, organizer, starts_at, ends_at, venue, fee_text, capacity, highlights, teaser, body, reg_status, published_at)
  SELECT admin.user_id, v.title, v.cat::event_category, v.org, v.s::timestamptz, v.e::timestamptz, v.venue, v.fee, v.cap, v.hl::jsonb, v.teaser, v.body, 'open'::reg_status, now()
  FROM admin, (VALUES
    ('UDM Grand Alumni Homecoming 2026', 'event', 'UDM Alumni Relations Office', '2026-12-05 16:00:00+08', '2026-12-05 22:00:00+08',
     'UDM Gymnasium, Mehan Gardens, Manila', 'Free for alumni · ₱350 per guest', NULL::int,
     '["Batch reunions for 2019–2025", "Outstanding Alumni Awards", "Variety show by the UDM alumni chorale"]',
     'An evening of batch reunions, a variety show and the awarding of this year’s Outstanding Alumni.',
     E'An evening of batch reunions, a variety show and the awarding of this year’s Outstanding Alumni.\n\nBatch coordinators may reserve tables of ten at the Alumni Affairs office.'),
    ('Alumni Job Fair 2026', 'career', 'Career & Placement Office', '2026-11-14 09:00:00+08', '2026-11-14 16:00:00+08',
     'UDM Quadrangle and Function Rooms 2–4', 'Free admission', 500,
     '["Partner employers across IT, BPO, healthcare and finance", "On-the-spot interviews", "Free resume clinic"]',
     'Partner employers hold on-the-spot interviews, with a resume clinic all day.',
     E'Partner employers hold on-the-spot interviews, with same-day offers for qualified applicants. Bring five copies of your resume and a valid ID.\n\nA resume clinic runs all day in Function Room 4.')
  ) v(title, cat, org, s, e, venue, fee, cap, hl, teaser, body)
  RETURNING event_id, title
),
agenda AS (
  INSERT INTO event_agenda_item (event_id, starts_at, title, sort)
  SELECT ev.event_id, v.t::time, v.title, v.sort
  FROM ev JOIN (VALUES
    ('UDM Grand Alumni Homecoming 2026', '15:00', 'Registration and batch check-in', 0),
    ('UDM Grand Alumni Homecoming 2026', '17:00', 'Opening program and awards', 1),
    ('UDM Grand Alumni Homecoming 2026', '19:00', 'Dinner and variety show', 2),
    ('UDM Grand Alumni Homecoming 2026', '21:00', 'Raffle draw and socials', 3),
    ('Alumni Job Fair 2026', '09:00', 'Booths open · initial screening', 0),
    ('Alumni Job Fair 2026', '10:30', 'Resume clinic (Function Room 4)', 1),
    ('Alumni Job Fair 2026', '13:00', 'Employer talks', 2),
    ('Alumni Job Fair 2026', '15:00', 'Final interviews', 3)
  ) v(ev, t, title, sort) ON v.ev = ev.title
  RETURNING 1
)
INSERT INTO event_reg_field (event_id, field_key, label, hint, options, sort)
SELECT ev.event_id, v.k, v.label, v.hint, v.opts::jsonb, v.sort
FROM ev JOIN (VALUES
  ('UDM Grand Alumni Homecoming 2026', 'guests', 'Guests you’re bringing', '₱350 per guest, payable at the registration desk', '["None", "1", "2", "3"]', 0),
  ('UDM Grand Alumni Homecoming 2026', 'seat', 'Seating preference', NULL, '["With my batch", "Open seating"]', 1)
) v(ev, k, label, hint, opts, sort) ON v.ev = ev.title;

-- Check
SELECT
  (SELECT count(*) FROM alumnus) AS alumni,
  (SELECT count(*) FROM alumnus WHERE user_id IS NOT NULL) AS alumni_with_account,
  (SELECT count(*) FROM user_account WHERE role = 'admin' AND email LIKE '%@example.com') AS dummy_admins,
  (SELECT count(*) FROM user_account WHERE role = 'dept' AND email LIKE '%@example.com') AS dummy_colleges,
  (SELECT count(*) FROM survey_response) AS surveys,
  (SELECT count(*) FROM employment_record) AS employment,
  (SELECT count(*) FROM event) AS events,
  (SELECT count(*) FROM job_posting) AS jobs;

COMMIT;
